-- Logical UTF-8 user content only. Operational pause/lease/retry metadata never consumes extra quota.
CREATE TRIGGER storage_monitoring_categories_insert AFTER INSERT ON monitoring_categories BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES(NEW.workspace_id);
 SELECT CASE WHEN EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND ((COALESCE(length(CAST(NEW.name AS BLOB)),0)+COALESCE(length(CAST(NEW.description AS BLOB)),0)+COALESCE(length(CAST(NEW.purpose AS BLOB)),0)+COALESCE(length(CAST(NEW.criteria_json AS BLOB)),0)))>0 AND records_bytes+((COALESCE(length(CAST(NEW.name AS BLOB)),0)+COALESCE(length(CAST(NEW.description AS BLOB)),0)+COALESCE(length(CAST(NEW.purpose AS BLOB)),0)+COALESCE(length(CAST(NEW.criteria_json AS BLOB)),0)))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=MAX(0,records_bytes+((COALESCE(length(CAST(NEW.name AS BLOB)),0)+COALESCE(length(CAST(NEW.description AS BLOB)),0)+COALESCE(length(CAST(NEW.purpose AS BLOB)),0)+COALESCE(length(CAST(NEW.criteria_json AS BLOB)),0)))) WHERE workspace_id=NEW.workspace_id;
END;
