 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES(NEW.workspace_id);
 SELECT CASE WHEN EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND ((COALESCE(length(CAST(NEW.name AS BLOB)),0)+COALESCE(length(CAST(NEW.description AS BLOB)),0)+COALESCE(length(CAST(NEW.purpose AS BLOB)),0)+COALESCE(length(CAST(NEW.criteria_json AS BLOB)),0))-(COALESCE(length(CAST(OLD.name AS BLOB)),0)+COALESCE(length(CAST(OLD.description AS BLOB)),0)+COALESCE(length(CAST(OLD.purpose AS BLOB)),0)+COALESCE(length(CAST(OLD.criteria_json AS BLOB)),0)))>0 AND records_bytes+((COALESCE(length(CAST(NEW.name AS BLOB)),0)+COALESCE(length(CAST(NEW.description AS BLOB)),0)+COALESCE(length(CAST(NEW.purpose AS BLOB)),0)+COALESCE(length(CAST(NEW.criteria_json AS BLOB)),0))-(COALESCE(length(CAST(OLD.name AS BLOB)),0)+COALESCE(length(CAST(OLD.description AS BLOB)),0)+COALESCE(length(CAST(OLD.purpose AS BLOB)),0)+COALESCE(length(CAST(OLD.criteria_json AS BLOB)),0)))>(CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END)) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=MAX(0,records_bytes+((COALESCE(length(CAST(NEW.name AS BLOB)),0)+COALESCE(length(CAST(NEW.description AS BLOB)),0)+COALESCE(length(CAST(NEW.purpose AS BLOB)),0)+COALESCE(length(CAST(NEW.criteria_json AS BLOB)),0))-(COALESCE(length(CAST(OLD.name AS BLOB)),0)+COALESCE(length(CAST(OLD.description AS BLOB)),0)+COALESCE(length(CAST(OLD.purpose AS BLOB)),0)+COALESCE(length(CAST(OLD.criteria_json AS BLOB)),0)))) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_monitoring_categories_delete AFTER DELETE ON monitoring_categories BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES(OLD.workspace_id);
 UPDATE workspace_storage_accounts SET records_bytes=MAX(0,records_bytes+(-(COALESCE(length(CAST(OLD.name AS BLOB)),0)+COALESCE(length(CAST(OLD.description AS BLOB)),0)+COALESCE(length(CAST(OLD.purpose AS BLOB)),0)+COALESCE(length(CAST(OLD.criteria_json AS BLOB)),0)))) WHERE workspace_id=OLD.workspace_id;
